// This file is generated by AI.

import { getCurrentWindow } from '@tauri-apps/api/window';
import { FluentProvider, webDarkTheme, webLightTheme } from '@fluentui/react-components';
import { useEffect } from 'react';

import { EditorPage } from './components/EditorPage';
import { SettingsDialog } from './components/SettingsDialog';
import { UnsavedDialog } from './components/UnsavedDialog';
import { WelcomePage } from './components/WelcomePage';
import { lspClient } from './lsp/client';
import { setMonacoTheme } from './lsp/monaco';
import { useAppStore } from './state/store';
import { confirmClose } from './unsaved';

export default function App() {
  const settings = useAppStore((s) => s.settings);
  const theme = useAppStore((s) => s.theme);
  const setTheme = useAppStore((s) => s.setTheme);
  const projectPath = useAppStore((s) => s.projectPath);

  // 解析主题 (light/dark/system -> light/dark)
  useEffect(() => {
    const apply = () => {
      const systemDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      const resolved = settings.theme === 'system' ? (systemDark ? 'dark' : 'light') : settings.theme;
      setTheme(resolved);
      document.documentElement.setAttribute('data-theme', resolved);
      setMonacoTheme(resolved === 'dark');
    };
    apply();
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    mq.addEventListener('change', apply);
    return () => mq.removeEventListener('change', apply);
  }, [settings.theme, setTheme]);

  // 启动 LSP 客户端 (应用级单例)
  useEffect(() => {
    void lspClient.start();
  }, []);

  // 退出程序时如有未保存更改则弹窗确认
  useEffect(() => {
    const win = getCurrentWindow();
    let allowClose = false;
    const unlisten = win.onCloseRequested((event) => {
      if (allowClose) return;
      const hasDirty = useAppStore.getState().documents.some((d) => d.dirty);
      if (!hasDirty) return; // 无未保存更改, 允许默认关闭
      event.preventDefault();
      confirmClose(() => {
        allowClose = true;
        void win.close(); // 重新触发 onCloseRequested, 此时 allowClose=true 放行
      });
    });
    return () => {
      void unlisten.then((f) => f());
    };
  }, []);

  return (
    <FluentProvider theme={theme === 'dark' ? webDarkTheme : webLightTheme} className="app-root">
      {projectPath ? <EditorPage /> : <WelcomePage />}
      {/* 设置/未保存对话框为应用级, 欢迎页与编辑页共用 */}
      <SettingsDialog />
      <UnsavedDialog />
    </FluentProvider>
  );
}
